statement.tex:
\begin{enumerate}
  \item 正の約数の個数がちょうど15個である最小の自然数を求めよ．
  \item 0以上の整数 $a,b$ に対し $n=2^a3^b$ とする．$n$ の正の約数の総和が 403 となるとき，$n$ を求めよ．
  \item (2) の $n$ の正の約数すべての積を，$12^k$ の形で表せ．
\end{enumerate}

\begin{enumerate}
  \item $100!$ が $12^k$ で割り切れるような最大の自然数 $k$ を求めよ．
  \item $n!$ が $3^{20}$ で割り切れるような最小の自然数 $n$ を求めよ．
  \item $n!$ を10進法で表したとき，末尾にちょうど30個の0が並ぶような自然数 $n$ は存在するか．
\end{enumerate}

\begin{enumerate}
  \item 整数 $n$ について，$n^2+n+1$ が7で割り切れるための条件を，$n$ を7で割った余りで答えよ．
  \item どのような整数 $n$ に対しても，$n^2+3n+5$ は121で割り切れないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $3^{2026}$ の下2桁を求めよ．
  \item $2^n+3^n$ が5で割り切れるような自然数 $n$ の条件を求めよ．
  \item $7^{(7^7)}$ の一の位の数を求めよ．
\end{enumerate}

$m<n$ である2つの自然数の最大公約数を $G$，最小公倍数を $L$ とする．
\begin{enumerate}
  \item $G+L=54,\ m+n=30$ を満たす $(m,n)$ をすべて求めよ．
  \item $L=6G,\ m+n=70$ を満たす $(m,n)$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $n$ に対し，$n^2+1$ と $n+3$ の最大公約数として取り得る値をすべて求めよ．
  \item $1\leqq n\leqq100$ で，$n^2+1$ と $n+3$ の最大公約数が5となる $n$ の個数を求めよ．
  \item $2^{60}-1$ と $2^{42}-1$ の最大公約数を求めよ．
\end{enumerate}

0以上の整数 $m,n$ を用いて $5m+8n$ と表せる自然数を「表せる数」と呼ぶ．
\begin{enumerate}
  \item 27 は表せる数でないことを示せ．
  \item 28 以上の整数はすべて表せる数であることを示せ．
  \item 表せる数でない自然数の個数を求めよ．
\end{enumerate}

$f(x)=ax^2+bx+c$（$a,b,c$ は実数）とする．
\begin{enumerate}
  \item $f(0),\ f(1),\ f(2)$ がすべて整数ならば，任意の整数 $n$ に対して $f(n)$ は整数であることを示せ．
  \item $f(x)=\frac12x^2+bx$ が任意の整数 $n$ に対して整数値をとるような実数 $b$ をすべて求めよ．
\end{enumerate}

$f(x)=ax^3+bx$（$a,b$ は実数）とする．
\begin{enumerate}
  \item $f(x)=A\,x(x-1)(x-2)+B\,x(x-1)+C\,x$ となる定数 $A,B,C$ を $a,b$ で表せ．
  \item 任意の整数 $n$ に対し $f(n)$ が整数となるための必要十分条件は，「$6a$ と $a+b$ がともに整数」であることを示せ．
  \item $0<a<1,\ 0<b<1$ で (2) の条件を満たす組 $(a,b)$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $13x+31y=1000$ を満たす正の整数の組 $(x,y)$ をすべて求めよ．
  \item $17x+23y=n$ を満たす正の整数の組 $(x,y)$ が存在しないような自然数 $n$ のうち，最大のものを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x^2=y^2+2026$ を満たす自然数 $x,y$ は存在しないことを示せ．
  \item $2xy-3x+4y=20$ を満たす整数の組 $(x,y)$ をすべて求めよ．
\end{enumerate}

次の等式を満たす正の整数の組 $(x,y)$ をすべて求めよ．
\begin{enumerate}
  \item $\dfrac2x+\dfrac3y=1$
  \item $\dfrac1x-\dfrac1y=\dfrac16$
\end{enumerate}

\begin{enumerate}
  \item $n^2+20n+7$ が平方数となる自然数 $n$ をすべて求めよ．
  \item 自然数 $a,b,c$ が $a^2+b^2=c^2$ を満たすとき，$ab$ は6の倍数であることを示せ．
\end{enumerate}

solutions.tex:
$a\leqq b\leqq c$ より $abc=2(a+b+c)\leqq6c$，よって $ab\leqq6$．$a\geqq3$ なら $ab\geqq9$ で不適なので $a=1,2$．
\begin{itemize}
  \item $a=1$：$bc=2(1+b+c)\iff(b-2)(c-2)=6$．$b-2\geqq-1$ で，$b=1$ なら $c-2=-6$ で $c<0$，$b=2$ なら左辺 $0$ で不適．よって $1\leqq b-2\leqq c-2$ で $(b-2,c-2)=(1,6),(2,3)$，$(b,c)=(3,8),(4,5)$．
  \item $a=2$（$b\leqq3$）：$2bc=2(2+b+c)\iff(b-1)(c-1)=3$．$b=2$ なら $c=4$，$b=3$ なら $c-1=\frac32$ で不適．$(b,c)=(2,4)$．
\end{itemize}
よって $\boldsymbol{(1,3,8),\ (1,4,5),\ (2,2,4)}$．

statement.tex:
$x,y$ 座標がともに整数である点を格子点という．
\begin{enumerate}
  \item 直線 $3x+5y=60$ 上で $x\geqq0,\ y\geqq0$ を満たす格子点の個数を求めよ．
  \item $x\geqq0,\ y\geqq0,\ 3x+5y\leqq60$ を満たす格子点の個数を求めよ．
  \item $x>0,\ y>0,\ 3x+5y<60$ を満たす格子点の個数を求めよ．
\end{enumerate}

3辺の長さが整数である直角三角形を考える（斜辺を $c$，他の2辺を $a\leqq b$ とする）．
\begin{enumerate}
  \item 内接円の半径が2であるものをすべて求めよ．
  \item 面積と周の長さ（の数値）が等しいものは，(1)で求めたものに限ることを示せ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $a$ について，$a\geqq9$ ならば $a^3-3a^2-40a-48>0$ であることを示せ．
  \item 自然数 $a$ に対して $b=\dfrac{5a^2+40a+48}{a^3+2a^2}$ とおく．$b$ も自然数となるような組 $(a,b)$ をすべて求めよ．
\end{enumerate}

$x,y$ 座標がともに整数である点を格子点という．$\sqrt3$ が無理数であることは証明なしに用いてよい．
\begin{enumerate}
  \item 直線 $y=\dfrac{x}{2-\sqrt3}-\sqrt3$ が通る格子点をすべて求めよ．
  \item 原点を通り，原点以外の格子点も通る2直線のなす角は $45^\circ$ にはなり得るが，$30^\circ$ にはなり得ないことを示せ．
  \item 3つの頂点がすべて格子点である正三角形は存在しないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item 1から $2n$ までの整数から $n+1$ 個を選ぶと，その中に一方が他方を割り切る2数が必ず含まれることを示せ．
  \item $1\leqq l\leqq100$ かつ $|l\sqrt2-m|<\dfrac1{100}$ を満たす整数 $l,m$ が存在することを示せ．また，そのような $(l,m)$ を1組具体的に求めよ．
\end{enumerate}

$a_1=a_2=1,\ a_{n+2}=a_{n+1}+a_n$ で定められる数列について，
\begin{enumerate}
  \item $a_n$ を4で割った余りを $n=1,\dots,12$ について求め，周期を答えよ．
  \item $a_{2026}$ を4で割った余りを求めよ．
  \item $a_n$ が3の倍数となるのは $n$ が4の倍数のときに限ることを示せ．
\end{enumerate}

$p\leqq q\leqq r$ を満たす正の整数 $p,q,r$ について，
\begin{enumerate}
  \item $\dfrac1p+\dfrac1q=\dfrac13$ を満たす $(p,q)$ をすべて求めよ．
  \item $\dfrac1p+\dfrac1q+\dfrac1r=\dfrac56$ を満たす $(p,q,r)$ をすべて求めよ．
\end{enumerate}

正の整数 $a,b,c$ が $a^2+b^2=c^2$ を満たすとする．
\begin{enumerate}
  \item 整数の2乗を5で割った余りは0，1，4のいずれかであることを示せ．
  \item $a,b,c$ のうち少なくとも1つは5の倍数であることを示せ．
  \item $c=25$ のとき，$(a,b)$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $p,\ p+10,\ p+14$ がいずれも素数となる $p$ をすべて求めよ．
  \item $q,\ q+2,\ q+6,\ q+8,\ q+14$ がいずれも素数となる $q$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての自然数 $n$ に対し，$n^3+2n$ と $n^4+3n^2+1$ は互いに素であることを示せ．
  \item 自然数 $n$ について，$n+3$ と $n^2+5$ の最大公約数としてありうる値をすべて求めよ．また，$1\leqq n\leqq100$ のうち $n+3$ と $n^2+5$ が互いに素でない $n$ の個数を求めよ．
\end{enumerate}

整数からなる数列 $\{a_n\}$ を $a_1=1,\ a_2=4,\ a_{n+2}=4a_{n+1}-a_n$ で定める．
\begin{enumerate}
  \item $a_n$ が偶数となることと，$n$ が偶数となることは同値であることを示せ．
  \item $a_n$ が30の倍数となるための条件を (1) と同様の形式で求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a+b=a^2-ab+b^2$ をみたす正の整数の組 $(a,b)$ をすべて求めよ．
  \item $a^3+b^3=p^2$ をみたす素数 $p$ と正の整数 $a,b$ の組 $(a,b,p)$ をすべて求めよ．
\end{enumerate}

2以上の整数 $n$ に対し，方程式 $x_1+x_2+\cdots+x_n=x_1x_2\cdots x_n$ の正の整数解で $x_1\leqq x_2\leqq\cdots\leqq x_n$ をみたすものを考える．
\begin{enumerate}
  \item $n=4$，$n=5$ のときの解をすべて求めよ．
  \item 解のうち，1がちょうど $n-2$ 個含まれるものの個数は，$n-1$ の正の約数の個数を $d$ とするとき $\Bigl[\dfrac{d+1}2\Bigr]$ であることを示せ（$[x]$ は $x$ を超えない最大の整数）．これを用いて $n=13$ のとき1が11個含まれる解をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{227}{98}=a_1+\cfrac1{a_2+\cfrac1{a_3+\cfrac1{a_4}}}$（$a_i$ は正の整数）と表せ．
  \item $a_1+\cfrac1{a_2+\cfrac1{a_3}}=\dfrac pq$（既約分数）とするとき，$227q-98p$ の値を求めよ．
  \item $227x-98y=5$ の整数解をすべて求めよ．
\end{enumerate}

$N$ を正の整数とする．$2N$ 個の項からなる数列 $\{a_1,\dots,a_N,b_1,\dots,b_N\}$ を $\{a_1,b_1,a_2,b_2,\dots,a_N,b_N\}$ という数列に並べ替える操作を「シャッフル」と呼ぶ．数列 $\{1,2,\dots,2N\}$ をシャッフルしたとき，数 $k$ が現れる位置を $f(k)$ で表す．
\begin{enumerate}
  \item 数列 $\{1,2,\dots,10\}$ を2回シャッフルしたときに得られる数列を求めよ．
  \item $1\leqq k\leqq2N$ をみたす任意の整数 $k$ に対し，$f(k)-(2k-1)$ は $2N-1$ で割り切れることを示せ．
  \item $n$ を正の整数とし，$N=2^{n-1}$ とする．数列 $\{1,2,\dots,2N\}$ を $n$ 回シャッフルすると元に戻ることを証明せよ．
\end{enumerate}

各辺の長さが整数である直角三角形（直角をはさむ辺 $a\leqq b$，斜辺 $c$）を考える．
\begin{enumerate}
  \item 内接円の半径 $r$ は整数であることを示せ．
  \item 面積と周の長さが等しいような直角三角形をすべて求めよ．
\end{enumerate}

自然数 $a$ に対して $b=\dfrac{a^2+53a+12}{a^3+3a^2+2a}$ とおく．
\begin{enumerate}
  \item $a\geqq7$ ならば $0<b<1$ であることを示せ．
  \item $b$ も自然数となるような組 $(a,b)$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $n$ を正の整数とし，$x_1,\dots,x_{n+1}$ を区間 $0\leqq x\leqq1$ 上の異なる点とする．$0<x_k-x_j\leqq\dfrac1n$ をみたす $j,k$ が存在することを示せ．
  \item $\omega$ を正の無理数とする．任意の正の整数 $n$ に対して $0<l\omega+m\leqq\dfrac1n$ をみたす整数 $l,m$ が存在することを示せ．
  \item $\omega=\sqrt2$，$n=10$ のとき，(2) をみたす $(l,m)$ を1組挙げよ．
\end{enumerate}

座標空間で，3つの座標がすべて整数である点を格子点という．
\begin{enumerate}
  \item どの2点を選んでもその中点が格子点にならないような8個の格子点の例を挙げ，理由を述べよ．
  \item 任意の9個の格子点からは，中点が格子点となる2点を必ず選べることを示せ．
\end{enumerate}

自然数 $n$ に対して，$n!!$ を $n$ が偶数のとき $n(n-2)\cdots4\cdot2$，$n$ が奇数のとき $n(n-2)\cdots3\cdot1$ と定める．
\begin{enumerate}
  \item $1000!!$ を素因数分解したときの素因数2の個数と素因数5の個数を求めよ．また，$1000!!$ を10進法で表したとき，末尾に連続して並ぶ0の個数を求めよ．
  \item $999!!$ を素因数分解したときの素因数5の個数を求めよ．
\end{enumerate}

自然数 $n$ の正の約数の個数を $\varphi(n)$，正の約数の総和を $S(n)$，正の約数の逆数の総和を $T(n)$ とする．
\begin{enumerate}
  \item $\varphi(720)$，$S(720)$，$T(720)$ を求めよ．
  \item 任意の $n$ に対して $T(n)=\dfrac{S(n)}{n}$ であることを示せ．
  \item $m$ を自然数，$p$ を5以上の素数として $n=2^m\cdot3\cdot p$ と表されるとき，$T(n)=3$ となる $n$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $a,b$ と整数 $q,r$ が $a=bq+r$ を満たすとき，$\gcd(a,b)=\gcd(b,r)$ であることを示せ．
  \item 自然数 $n$ に対して $\gcd(n^2+3,\ n+2)$ がとりうる値をすべて求めよ．また，その値が1でないような $n$ の条件を求めよ．
  \item すべての自然数 $n$ に対して $3n+1$ と $5n+2$ が互いに素であることを示し，$(3n+1)x+(5n+2)y=1$ を満たす整数 $x,y$ の組を1つ（$n$ を用いて）求めよ．
\end{enumerate}

$x,y$ を整数とする．
\begin{enumerate}
  \item $x^7-x$ は42の倍数であることを示せ．
  \item $x^7y-xy^7$ は42の倍数であることを示せ．
  \item すべての整数 $x,y$ に対して $x^7y-xy^7$ を割り切る最大の自然数を求めよ．
\end{enumerate}

自然数の組 $(x,y,z)$ が $x^2+y^2=z^2$ を満たすとする．
\begin{enumerate}
  \item $xy$ は3の倍数であることを示せ．
  \item $xy$ は4の倍数であることを示せ．
  \item $xyz$ は60の倍数であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item $2\leqq n\leqq2000$ を満たす整数 $n$ のうち，$\dfrac1n$ が有限小数となるものはいくつあるか．
  \item (1) のうち，$\dfrac1n$ がちょうど小数第4位で終わるものをすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 分数 $\dfrac9{14}$ を10進法の小数で表したとき，小数第100位の数字を求めよ．
  \item 10進法の整数9，14をそれぞれ3進法で表せ．
  \item 分数 $\dfrac9{14}$ を3進法の小数で表したとき，小数第100位の数字を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $|3x+3|<x^2+x+3$ を満たす実数 $x$ の範囲を求めよ．
  \item $\dfrac{3n+3}{n^2+n+3}$ が整数となるような整数 $n$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\log_23$ は無理数であることを示せ．
  \item 有理数 $q,r$ が $12^q=18^r$ を満たすならば $q=r=0$ であることを示せ．
  \item $\log_{12}18$ は無理数であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item 等式 $mn=3m+5n+12$ を満たす自然数 $m,n$ の組の総数を求めよ．
  \item 等式 $m^2n+mn+n=91$ を満たす自然数 $m,n$ の組をすべて求めよ．
  \item 等式 $m^3-m^2n+mn-n+m+26=0$ を満たす自然数 $m,n$ の組をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $xy=2(x+y)$，$x\geqq y$ となる正の整数の組 $(x,y)$ をすべて求めよ．
  \item $xyz=2(x+y+z)$，$x\geqq y\geqq z$ となる正の整数の組 $(x,y,z)$ をすべて求めよ．
  \item $wxyz=w+x+y+z+1$，$w\geqq x\geqq y\geqq z$ となる正の整数の組 $(w,x,y,z)$ をすべて求めよ．
\end{enumerate}

$n,m$ を0以上の整数とする．
\begin{enumerate}
  \item 整数 $x,y$ について，$x^2+y^2$ が7の倍数ならば $x,y$ はともに7の倍数であることを示せ．
  \item $x^2+y^2=10\cdot7^{2n}$ を満たす自然数の組 $(x,y)$ をすべて求めよ．
  \item $x^2+y^2=3\cdot7^m$ を満たす自然数 $x,y$ は存在しないことを示せ．
\end{enumerate}

$f(x)=x^3+ax^2+bx+c$（$a,b,c$ は整数）とする．
\begin{enumerate}
  \item 有理数 $r$ が $f(x)=0$ の解ならば，$r$ は整数であることを示せ．
  \item $f(0)$ と $f(1)$ がともに奇数ならば，$f(x)=0$ は有理数解をもたないことを示せ．
  \item 方程式 $x^3-3x^2+5x+7=0$ は有理数解をもたないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $a_1$ を0以上80以下の整数として，$3a_1$ を81で割った余りを $a_2$ とし，以下同様に $3a_n$ を81で割った余りを $a_{n+1}$ とする．
  $a_1=50$ を3進法で表し，$a_2,a_3,a_4$ を求めよ．また，$a_1$ によらず $a_n=0$ となる最小の $n$ と，$a_3=0$ となる $a_1$ の個数を求めよ．
  \item $c_1$ を0以上63以下の整数として，$2c_n+1$ を64で割った余りを $c_{n+1}$ とする．$c_1$ によらず $c_n$ が一定の値になる最小の $n$ と，その値を求めよ．
\end{enumerate}

サイコロを $n$ 回投げ，$k$ 回目に出た目を $a_k$ とする．また，$s_n$ を $s_n=\displaystyle\sum_{k=1}^n10^{n-k}a_k$ で定める．
\begin{enumerate}
  \item $n\geqq3$ のとき，$s_n$ が8で割り切れる確率を求めよ．また $n=2$ のときの確率を求めよ．
  \item $n\geqq2$ のとき，$s_n$ が12で割り切れる確率を求めよ．
  \item $s_n$ が7で割り切れる確率 $p_n$ を求めよ．また $p_n>\frac17$ となる $n$ の条件を求めよ．
\end{enumerate}

$a,b$ を正の整数とするとき，次を証明せよ．
\begin{enumerate}
  \item $a^5-a$ は30の倍数である．
  \item $a-b$ が5の倍数ならば，$a^5-b^5$ は25の倍数である．
  \item $a^5-b^5$ は，5の倍数ならば25の倍数である．
\end{enumerate}

\begin{enumerate}
  \item $x^2-y^2=2025$ をみたす正の整数 $x,y$ の組をすべて求めよ．
  \item $x^2+y^2=65$ をみたす正の整数 $x,y$ の組をすべて求めよ．
  \item $n$ を正の整数とする．$x^2+y^2=65^n$ をみたす正の整数 $x,y$ が存在することを示せ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $x,y$ は，$1<x<y$ および $\left(1+\dfrac1x\right)\left(1+\dfrac1y\right)=\dfrac32$ をみたす．$x,y$ の組をすべて求めよ．
  \item 自然数 $x,y,z$ は，$1<x<y<z$ および $\left(1+\dfrac1x\right)\left(1+\dfrac1y\right)\left(1+\dfrac1z\right)=2$ をみたす．$x,y,z$ の組をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $2^n+1=k^2$ をみたす正の整数の組 $(k,n)$ をすべて求めよ．
  \item $3^n=k^2-7$ をみたす正の整数の組 $(k,n)$ をすべて求めよ．
\end{enumerate}

3辺の長さ $x,y,z$ が $x<y<z$ を満たす整数である三角形があり，長さ $y$ の辺の対角が $60^\circ$ である．
\begin{enumerate}
  \item $x+z-y=k$ とおくとき，$(3x-2k)(3z-2k)=k^2$ を示せ．
  \item $x+z-y=4$ を満たす $x,y,z$ の組，$x+z-y=6$ を満たす $x,y,z$ の組をそれぞれすべて求めよ．
  \item $a$ を正の整数とする．$x+z-y=2^a$ を満たす $x,y,z$ の組の個数を $a$ の式で表せ．
