\begin{enumerate}
  \item 任意の整数 $a$ に対し，$a^2$ を7で割った余りは0，1，2，4のいずれかであることを示せ．
  \item 自然数 $a,b,c$ が $a^2+b^2=7c^2$ を満たすと仮定すると，$a,b,c$ はすべて7で割り切れなければならないことを証明せよ．
  \item $a^2+b^2=7c^2$ を満たす自然数 $a,b,c$ は存在しないことを証明せよ．
\end{enumerate}

$m$ を自然数とする．$3^mm!$ が $3^n$ で割り切れる自然数 $n$ の最大値を $N(m)$ とおくとき，
\begin{enumerate}
  \item $N(10)$ を求めよ．
  \item $m$ を3進法で表したときの各位の数の和を $s(m)$ とするとき，$N(m)=\dfrac{3m-s(m)}2$ を示せ．
  \item $N(m)<\dfrac{3m}2$ を示し，$N(m)=\dfrac{3m-1}2$ となる $m$ をすべて求めよ．
\end{enumerate}

0以上の整数 $x,y$ を用いて $n=7x+9y$ と表される整数 $n$ 全体の集合を $A$ とする．
\begin{enumerate}
  \item $A$ に属する整数のうち，小さい方から数えて3番目，4番目，9番目のものを求めよ．
  \item $m$ は整数であって，$n\geqq m$ を満たす整数 $n$ はすべて $A$ の要素であるという．このような整数 $m$ のうち最小のものを求めよ．
  \item 0以上の整数で $A$ に属さないものの個数を求めよ．
\end{enumerate}

$N$ を1以上の整数とする．$N$ の約数の和が，その整数の2倍になるときその整数 $N$ を完全数という．正の約数の和を $\sigma(N)$ で表す．
\begin{enumerate}
  \item 素数 $p$ と自然数 $k$ に対して $\sigma(p^k)$ を求め，$\dfrac{\sigma(p^k)}{p^k}<\dfrac p{p-1}$ を示せ．
  \item $k$ を自然数，$q$ を奇素数とする．$N=2^kq$ が完全数であるための必要十分条件は $q=2^{k+1}-1$ であることを示せ．
  \item 異なる2つの奇素数 $p,q$ と自然数 $a,b$ に対して，$N=p^aq^b$ は完全数でないことを示せ．
\end{enumerate}

$\alpha=\sqrt2+\sqrt3$ とする．
\begin{enumerate}
  \item 有理数 $p,q,r,s$ が $p+q\sqrt2+r\sqrt3+s\sqrt6=0$ をみたすならば $p=q=r=s=0$ であることを示せ．ただし $\sqrt2,\sqrt3,\sqrt{\frac32}$ が無理数であることは用いてよい．
  \item $\alpha$ は $x^4-10x^2+1=0$ の解であることを示せ．
  \item $P(x)$ は有理数を係数とする $x$ の多項式で，$P(\alpha)=0$ を満たしているとする．このとき $P(x)$ は $x^4-10x^2+1$ で割り切れることを証明せよ．
\end{enumerate}

実数 $x$ に対し，$x$ 以下の最大の整数を $[x]$ で表す．
\begin{enumerate}
  \item 整数 $m$ と実数 $x$ に対して，$[x+m]=[x]+m$ が成り立つことを示せ．
  \item 2以上の整数 $n$ と実数 $x$ に対して，$[nx]=[x]+\left[x+\dfrac1n\right]+\dots+\left[x+\dfrac{n-1}n\right]$ が成り立つことを示せ．
  \item 自然数 $N$ に対して，$\displaystyle\sum_{k=0}^\infty\left[\frac{N+2^k}{2^{k+1}}\right]=N$ が成り立つことを示せ（左辺は有限個の項を除いて0である）．
\end{enumerate}

$p,q$ を互いに素な自然数とする．自然数からなる数列 $\{a_n\}$ を，$a_1=p$，$a_2=q$，$a_{n+2}=a_{n+1}^2+a_na_{n+1}+a_n^2$（$n\geqq1$）で定める．
\begin{enumerate}
  \item すべての自然数 $m$ に対して，$a_m$ と $a_{m+1}$ が互いに素であることを証明せよ．
  \item すべての自然数 $m$ に対して，$a_m$ と $a_{m+2}$ が互いに素であることを証明せよ．
\end{enumerate}

\begin{enumerate}
