$r$ を0以上の整数とし，$a_1=r$，$a_2=r+1$，$a_{n+2}=a_{n+1}(a_n+1)$（$n=1,2,\dots$）で数列を定める．素数 $p$ を1つとり，$a_n$ を $p$ で割った余りを $b_n$ とする．
\begin{enumerate}
  \item $b_{n+2}$ は $b_{n+1}(b_n+1)$ を $p$ で割った余りと一致することを示せ．
  \item $r=3$，$p=11$ の場合に，$n\leqq10$ のすべての $n$ について $b_n$ を求めよ．
  \item 相異なる自然数 $n,m$ について $b_{n+1}=b_{m+1}>0$，$b_{n+2}=b_{m+2}$ が成り立つならば，$b_n=b_m$ であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item $a$ を7で割ると4余り，$b$ を7で割ると5余る．$2a+3b$，$a^2+b^2$，$a^3b$ を7で割った余りをそれぞれ求めよ．
  \item 整数 $a$ を7で割ると4余り，5で割ると2余る．$a$ を35で割った余りと，$a^2$ を35で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $1001^5+2002^5+3003^5+4004^5+5005^5$ を6で割った余りを求めよ．
  \item $3^{2026}$ を28で割った余りを求めよ．
  \item $5^{5^5}$ を36で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x$ が7で割って4余る整数のとき，$x^5-3x^3+2x+1$ を7で割った余りを求めよ．
  \item $x$ を7で割った余りが何であっても $x^7-x+3$ を7で割った余りは一定であることを示し，その値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $A$ を11で割った余りは，$A$ の各桁の数を一の位から交互に足し引きした値を11で割った余りに等しいことを示せ．
  \item $A$ を一の位から3桁ずつ区切り，その区切りを $B_1,B_2,\dots$ とする．$A\equiv B_1-B_2+B_3-\cdots\pmod{1001}$ を示せ．
  \item $A=123456789123$ を7，11，13で割った余りをそれぞれ求めよ．
\end{enumerate}

$n$ を任意の整数とする．
\begin{enumerate}
  \item $n^7-n$ は2，3，7の倍数であることを示せ．
  \item $n^7-n$ は5の倍数とは限らないことを示せ．
  \item すべての整数 $n$ について $n^7-n$ を割り切る最大の自然数を求めよ．
\end{enumerate}

正の整数の数列 $a_n=17^n+3\cdot37^{n-1}$（$n=1,2,3,\dots$）を考える．
\begin{enumerate}
  \item $a_1$，$a_2$ を求め，素因数分解せよ．
  \item すべての $a_n$ は20の倍数であることを示せ．
  \item すべての $a_n$ を割り切る最大の自然数を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 任意の整数 $n$ について $n(n^2+11)$ は6の倍数であることを示せ．
  \item $2^n+3^n$ が7の倍数となる自然数 $n$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 0以上のすべての整数 $n$ に対して $4^{2n+1}+3^{n+2}$ が13の倍数であることを証明せよ．
  \item $4^{2n+1}+3^{n+2}$ が169の倍数となる最小の0以上の整数 $n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 整数 $x,y$ について，$x^2+y^2$ が7の倍数ならば $x,y$ はともに7の倍数であることを証明せよ．
  \item $x^2+y^2=14182$ をみたす整数 $x,y$ は存在しないことを証明せよ．
\end{enumerate}

直線 $l:y=\frac35x+\frac13$ を考える．
\begin{enumerate}
  \item $l$ 上に格子点は存在しないことを示せ．
  \item $l$ と格子点の距離の最小値を求めよ．
  \item $l$ との距離が最小となる格子点のうち，原点に近いものから順に3点求めよ．
\end{enumerate}

\begin{enumerate}
  \item どのような自然数 $p$ に対しても $p(p^4+q)$ が30の倍数となるような自然数 $q$（$q<100$）をすべて求めよ．
  \item $m<n$ をみたす自然数 $m,n$ で，$m^n+1$，$n^m+1$ がともに13の倍数となるもののうち，$m+n$ が最小のものを求めよ．
  \item 3以上99999以下の整数 $a$ で，$a^2-a$ が100000で割り切れるものをすべて求めよ．
\end{enumerate}

$S=\{6x+10y+15z\mid x,y,z\text{ は整数}\}$，$T=\{6x+10y+15z\mid x,y,z\text{ は0以上の整数}\}$ とする．
\begin{enumerate}
  \item $S$ の正の最小要素を $d$ とするとき，$S=\{md\mid m\text{ は整数}\}$ を示し，$d$ を求めよ．
  \item 6，10，15 のどの2つも1でない公約数をもつことに注意して，$d$ が (1) の値になる理由を説明せよ．
  \item $T$ に属さない自然数の最大値を求めよ．
\end{enumerate}

各辺の長さが整数の直角三角形（斜辺 $c$，他の2辺 $a\leqq b$）の内接円の半径を $r$ とする．
\begin{enumerate}
  \item $(a-2r)(b-2r)=2r^2$ を示せ．
  \item $\dfrac{abc}{a+b+c}=rc$ を示し，これが整数であることを示せ．
  \item $r=6$ となる直角三角形は何個あるか．すべて求めよ．
\end{enumerate}

自然数 $n$ に対して $g(n)=2^{4n}+2^{3n}+2^{2n}+2^n+1$ とする．
\begin{enumerate}
  \item $n$ が5の倍数でないとき，$g(n)$ は31で割り切れることを示せ．
  \item $n$ が5の倍数のとき，$g(n)$ を31で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $p$，$p^2+2$，$p^3+2$ がいずれも素数であるような $p$ をすべて求めよ．
  \item $q$，$q+2$，$q+6$，$q+8$，$q+14$ がいずれも素数であるような $q$ をすべて求めよ．
\end{enumerate}

$a,b,c$ は $1<a<b<c$ をみたす整数で，$ab+bc+ca+1$ は $abc$ で割り切れるとする．
\begin{enumerate}
  \item $\dfrac{ab+bc+ca+1}{abc}=1$ を示せ．
  \item $a,b,c$ の組をすべて求めよ．
\end{enumerate}

次を証明せよ．
\begin{enumerate}
  \item $n\geqq2$ のとき，$1+\dfrac13+\dfrac15+\dots+\dfrac1{2n-1}$ は整数でない．
  \item $\displaystyle\sum_{k=0}^\infty\frac1{(2k)!}=1+\frac1{2!}+\frac1{4!}+\cdots$ は無理数である．
\end{enumerate}

$S=\{7x+11y\mid x,y\text{ は自然数}\}$ とする．
\begin{enumerate}
  \item $K=\{(x,y)\mid 1\leqq x\leqq10,\ 1\leqq y\leqq6\}$ の点のうち $7x+11y<77$ をみたすものの個数を求めよ．
  \item $S$ に属さない自然数の最大値と，$S$ に属さない自然数の個数を求めよ．
  \item 1以上100以下の自然数のうち $S$ に属するものの個数を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\log_612$ は無理数であることを証明せよ．
  \item $x>1$ の範囲で方程式 $x^x=2$ はただ1つの解をもち，その解は無理数であることを証明せよ．
  \item $a,b$ がともに無理数で $a^b=3$ となる例を1組あげ，$a,b$ が無理数であることを示せ．
\end{enumerate}

$y_n=(2+\sqrt5)^n+(2-\sqrt5)^n$（$n=1,2,\dots$）とする．
\begin{enumerate}
  \item $y_{n+2}=4y_{n+1}+y_n$ を示し，$y_n$ が整数であることを示せ．
  \item $y_n\equiv2^{n+1}\pmod5$ を示せ．
  \item $(2+\sqrt5)^n$ を超えない最大の整数を5で割った余りを，$n$ を4で割った余りで分類して求めよ．
\end{enumerate}

$p$ は自然数，$f(x)=ax^2+bx+c$（$a,b,c$ は実数）とする．
\begin{enumerate}
  \item すべての実数 $x$ に対して $f(x)=\dfrac{2f(0)(x-1)(x-3)-3f(1)x(x-3)+f(3)x(x-1)}6$ が成り立つことを示せ．
  \item $f(0)$，$f(1)$，$f(3)$ がすべて $p$ の倍数であっても，$f(n)$ がすべての整数 $n$ で $p$ の倍数とは限らないことを，$p=2$ の例で示せ．
  \item 「すべての整数 $n$ に対して $f(n)$ が $p$ の倍数」であるための必要十分条件は，「$f(0)$，$f(1)$，$f(3)$ が $p$ の倍数で，かつ $f(3)-f(0)$ が $3p$ の倍数」であることを示せ．
\end{enumerate}

\begin{enumerate}
  \item 整数係数の整式 $f(x)$ について，整数 $n$ が $f(x)=0$ の解ならば，任意の整数 $m\neq n$ に対して $f(m)$ は $m-n$ で割り切れることを示せ．
  \item 方程式 $x^5+4x^4-19x^3+13x^2-22x-105=0$ の整数解をすべて求めよ．ただし，$f(1)$，$f(-1)$，$f(2)$ の値を用いて候補を絞ること．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $x^2-y^2=2025$ の整数解 $(x,y)$ の個数を求めよ．また，$x^2-y^2=2026$ は整数解をもたないことを示せ．
  \item 2以上の個数の連続する正の整数の和として表すことのできる正の整数 $N$ は，2のべきでない数に限ることを示せ（逆に2のべきでない数は表せることも示せ）．
  \item 2025 を2個以上の連続する正の整数の和として表す方法は何通りあるか．
\end{enumerate}

3辺の長さ $a,b,c$（$c$ が斜辺）がすべて整数である直角三角形について，次を示せ．
\begin{enumerate}
  \item $abc$ は 60 の倍数である．また，60 はそのような定数の最大値である．
  \item 内接円の半径は整数である．
\end{enumerate}

$p$ を3以上の素数とする．
\begin{enumerate}
  \item $1\leqq k\leqq p-1$ の各 $k$ に対して，$kk'\equiv1\pmod p$ をみたす $k'$（$1\leqq k'\leqq p-1$）がただ1つ存在することを示せ．
  \item $k'=k$ となるのは $k=1,\,p-1$ に限ることを示し，$(p-1)!\equiv-1\pmod p$ を示せ．
  \item $99!$ および $97!$ を 101 で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a,b$ は互いに素な2以上の整数とする．$ma-nb=1$ をみたす正の整数 $m,n$ で $n\leqq a-1$ となるものが存在することを示せ．
  \item 3289 と 2717 の最大公約数 $d$ を求めよ．
  \item $3289x+2717y=d$ をみたす整数 $(x,y)$ をすべて求め，そのうち $|x|+|y|$ が最小となるものを求めよ．
\end{enumerate}

\begin{enumerate}
  \item 正の約数の個数がちょうど 30 個である最小の正の整数を求めよ．
  \item 正の整数 $a,b$ に対して $n=2^a\cdot3^b$ とし，$n$ の正の約数の総和を $S$ とする．$S=\dfrac{65}{24}n$ となる $a,b,n$ を求めよ．
\end{enumerate}

正の整数 $N$ を10進法で書き，下の位から3桁ずつ区切った数を $c_0,c_1,\dots,c_m$ とする（$N=\sum c_k\cdot1000^k$，$0\leqq c_k\leqq999$）．$T=c_0-c_1+c_2-\dots+(-1)^mc_m$ とおく．
\begin{enumerate}
  \item $N\equiv T\pmod{1001}$ を示し，$N$ が 7 で割り切れる条件を $T$ で述べよ．
  \item 「2026」を10回続けて書いた40桁の数 $N=20262026\cdots2026$ を 1001，7，11，13 で割った余りをそれぞれ求めよ．
\end{enumerate}

$A=\{1,2,\dots,81\}$ とする．$A$ の要素を $3^e\cdot r$（$e\geqq0$，$r$ は3で割り切れない正の整数）と表し，同じ $r$ をもつ要素を集めた集合を $A_r$ とする．
\begin{enumerate}
  \item $A_r$ は全部で何個あるか．また $A$ の各要素はちょうど1つの $A_r$ に属することを示せ．
  \item $A$ の部分集合 $B$ の要素が55個以上あれば，$\dfrac yx$ が3のべき（$3,9,27,\dots$）となる $B$ の要素 $x,y$ が存在することを示せ．
  \item 54個の要素からなる $A$ の部分集合で，どの2つの要素の比も3のべきにならないものを1つ求めよ．
\end{enumerate}

\begin{enumerate}
  \item 不等式 $\dfrac{2026}n-\dfrac{2026}{n+1}\geqq1$ をみたす最大の正の整数 $n$ を求めよ．
  \item 2026 個の整数 $\left[\dfrac{2026}1\right],\left[\dfrac{2026}2\right],\dots,\left[\dfrac{2026}{2026}\right]$ の中に異なる整数は何個あるか．
\end{enumerate}

$x,y,z,w$ は正の整数とする．
\begin{enumerate}
  \item $\dfrac1x+\dfrac1y+\dfrac1z=\dfrac12$ をみたす組 $(x,y,z)$（順序を区別する）は何通りあるか．
  \item $r$ を正の有理数とするとき，$\dfrac1x+\dfrac1y+\dfrac1z+\dfrac1w=r$ をみたす組 $(x,y,z,w)$ は有限個であることを示せ．
\end{enumerate}

自然数 $m\geqq2$ に対し，$\binom m1,\binom m2,\dots,\binom m{m-1}$ の最大公約数を $d_m$ とする．
\begin{enumerate}
  \item 素数 $p$ が $m$ を割り切り，$p^e$ が $m$ を割り切る最大の $p$ のべきであるとき，$\binom m{p^e}$ は $p$ で割り切れないことを示せ（$p^e<m$ とする）．
  \item $m$ が素数 $p$ のべき $p^k$（$k\geqq1$）のとき $d_m=p$，$m$ が異なる2つ以上の素因数をもつとき $d_m=1$ であることを示せ．
  \item $d_{2026}$，$d_{2048}$，$d_{2187}$ を求めよ．
\end{enumerate}

$n$ を2以上の自然数とし，整式 $x^n$ を $x^2-6x-15$ で割った余りを $a_nx+b_n$ とする．
\begin{enumerate}
  \item $a_{n+1},\,b_{n+1}$ を $a_n,\,b_n$ で表せ．
  \item 各 $n$ に対して，$a_n$ と $b_n$ の公約数で素数となるものをすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $T\geqq1$ を実数とする．$T\leqq n(n+1)<T+2\sqrt T+2$ をみたす自然数 $n$ が存在することを示せ．
  \item 連続する2つの自然数の積で，10進法で表したとき先頭から7が99個以上連続して並ぶものが存在することを示せ．
\end{enumerate}

整数 $m$ に対し，$f(x)=x^2-mx+\dfrac m3+1$ とおく．
\begin{enumerate}
  \item 方程式 $f(x)=0$ が整数の解を少なくとも1つもつような $m$ の値をすべて求めよ．
  \item 不等式 $f(x)\leqq0$ をみたす整数 $x$ がちょうど4個あるような $m$ の値をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 等式 $(x^2-3y^2)(z^2-3t^2)=(xz+3yt)^2-3(xt+yz)^2$ を示せ．
  \item $x^2-3y^2=-2$ の自然数解 $(x,y)$ は無数に存在することを示し，$x>1000$ となる解を1組求めよ．
  \item $x^2-3y^2=-1$ は整数解をもたないことを示せ．
\end{enumerate}

自然数 $n,p$ に対し，$n^p$ を100で割った余り（下2桁）を $g_p(n)$ とする．
\begin{enumerate}
  \item すべての自然数 $n$ に対して $g_{22}(n)=g_2(n)$ であることを示せ．また，$g_{21}(n)=g_1(n)$ がすべての $n$ では成り立たないことを示せ．
  \item $n$ が自然数全体を動くとき，$g_{100}(n)$ のとる値をすべて求めよ．
  \item $1\leqq n\leqq100$ で $g_{2026}(n)=1$ となる $n$ をすべて求めよ．
\end{enumerate}

自然数 $n$ に対し $T(n)=\displaystyle\sum_{k=1}^{11}k^n$ とおく．
\begin{enumerate}
  \item すべての自然数 $n$ に対して $n^{11}-n$ は11の倍数であることを示せ．
  \item $2^n$ を11で割った余りが1となる最小の自然数 $n$ を求めよ．
  \item $T(n)$ を11で割った余りを，$n$ の値によって分類して求めよ．
\end{enumerate}

$p$ を5以上の素数とし，$x,y$ は $0\leqq x<y\leqq p$ をみたす整数とする．
\begin{enumerate}
  \item $x^2$ と $y^2$ を $3p$ で割った余りが等しくなるための $x,y$ の条件を求めよ．
  \item (1) の条件をみたす組 $(x,y)$ の個数を $p$ で表せ．
  \item $x^2$ と $y^2$ を $6p$ で割った余りが等しくなる組 $(x,y)$ は存在しないことを示せ．
\end{enumerate}

整数 $a,b,c$ に対して $S(n)=\displaystyle\sum_{k=1}^n(ak^3+bk^2+ck+1)$ とおく．
\begin{enumerate}
  \item すべての自然数 $n$ に対して $S(n)$ が $n$ で割り切れるための $a,b,c$ の必要十分条件を求めよ．
  \item $m$ を自然数とする．(1) の条件をみたし，$0<a\leqq12m$，$0<b\leqq12m$，$0<c\leqq12m$ である整数の組 $(a,b,c)$ の個数を $m$ で表せ．
\end{enumerate}

$N$ を正の整数とする．$N$ の正の約数 $n$ に対し $f(n)=n+\dfrac Nn$ とおく．次の各 $N$ に対して $f(n)$ の最小値を求めよ．
\begin{enumerate}
  \item $N=3^k$（$k$ は正の整数）
  \item $N=8!$
\end{enumerate}

$n$ を2以上の整数，$X,Y$ を実数とする．実数 $u$ に対して，$u$ と $u$ に最も近い整数との距離を $\|u\|$ で表す．
次のことを示せ．
\begin{center}
$1\leqq j\leqq n^2-1$ をみたす整数 $j$ で，$\|jX\|\leqq\dfrac1n$ かつ $\|jY\|\leqq\dfrac1n$ となるものが存在する．
\end{center}

$a,b,c$ を整数とし，$f(x)=x^3+ax^2+bx+c$ を考える．
\begin{enumerate}
  \item $f(\alpha)=0$ となる有理数 $\alpha$ があれば，$\alpha$ は整数であることを示せ．
  \item $f(x)=0$ が有理数解をもつとする．任意の整数 $l$ と任意の自然数 $n$ に対して，$n$ 個の整数 $f(l),f(l+1),\dots,f(l+n-1)$ のうち少なくとも1つは $n$ で割り切れることを示せ．
  \item 任意の整数 $k$ に対して，方程式 $x^3-x+2k+1=0$ は有理数解をもたないことを示せ．
\end{enumerate}

整数を係数とする4次式 $f(x)$ が，次の条件をみたしている．
\begin{center}
(＊)\quad 任意の自然数 $n$ に対し，$f(n)$ は $n(n+1)(n+2)$ で割り切れる．
\end{center}
\begin{enumerate}
  \item ある整数 $a\ (\neq0),\ b$ があって $f(x)=x(x+1)(x+2)(ax+b)$ となることを示せ．
  \item さらに $x^4$ の係数が2で $f(1)=30$ であるとき，$f(x)$ を求めよ．
\end{enumerate}

実数 $a,b,c,d$ に対して $f(x)=ax^4+bx^3+cx^2+dx$ とする．$\binom xk=\dfrac{x(x-1)\cdots(x-k+1)}{k!}$ とおく．
\begin{enumerate}
  \item 次の3条件は同値であることを示せ．
  \begin{enumerate}
    \item すべての整数 $n$ に対して $f(n)$ は整数．
    \item $f(1),f(2),f(3),f(4)$ はすべて整数．
    \item 整数 $p,q,r,s$ を用いて $f(x)=p\binom x4+q\binom x3+r\binom x2+s\binom x1$ と表される．
  \end{enumerate}
  \item (1) の条件をみたし，$0\leqq a<1$，$0\leqq b<1$，$0\leqq c<1$，$0\leqq d<1$ である組 $(a,b,c,d)$ の個数を求めよ．
\end{enumerate}

$a,b,c,d$ を整数とし，座標平面上の点 $(x,y)$ を点 $(ax+by,\ cx+dy)$ に移す移動を $f$ とする．$f$ を $n$ 回続けて行う移動 $f^n$（$f^0$ は点を動かさない移動）は，点 $(x,y)$ を点 $(a_nx+b_ny,\ c_nx+d_ny)$ に移す（$a_n,b_n,c_n,d_n$ は整数で，$a_0=d_0=1$，$b_0=c_0=0$）．$p$ を素数とする．
\begin{enumerate}
  \item ある自然数 $k$ について $c_k$ が $p$ で割り切れるならば，すべての自然数 $m$ について $c_{mk}$ も $p$ で割り切れることを示せ．
  \item $ad-bc$ は $p$ で割り切れないとし，$c_n$ が $p$ で割り切れるような最小の自然数 $n$ を $k$ とする．このとき，自然数 $n$ について「$c_n$ が $p$ で割り切れる $\iff$ $n$ が $k$ の倍数」を示せ．
  \item $a=b=c=1$，$d=0$ とする．$c_n$ が7で割り切れるための $n$ の条件，11で割り切れるための $n$ の条件をそれぞれ求めよ．
\end{enumerate}

$a,b$ を互いに素な正の整数とする．正の整数 $n$ に対して整数 $a_n,b_n$ を $(a+b\sqrt3)^n=a_n+b_n\sqrt3$ で定める（$\sqrt3$ が無理数であることは用いてよい）．
\begin{enumerate}
  \item $a,b$ がともに奇数であるか，$a$ が3の倍数であるならば，$a_2$ と $b_2$ は互いに素でないことを示せ．
  \item $a+b$ が奇数で，$a$ が3の倍数でないならば，すべての $n$ に対して $a_n$ と $b_n$ は互いに素であることを示せ．
\end{enumerate}

正の整数全体で定義された実数値関数 $f$ が，次の (i)〜(iii) をみたす．
\begin{itemize}
  \item[(i)] 任意の正の整数 $m,\ n$ に対して $f(mn)=f(m)f(n)$．
  \item[(ii)] 任意の正の整数 $n$ に対して $f(n)<f(n+1)$．
  \item[(iii)] $f(2)=a$（$a$ は $a>1$ をみたす実数の定数）．
\end{itemize}
\begin{enumerate}
  \item $f(1)=1$ であり，$n\geqq2$ のとき $f(n)>1$ であることを示せ．
  \item 2以上の整数 $n$ と正の整数 $k$ に対し，$2^p\leqq n^k<2^{p+1}$ をみたす0以上の整数 $p$ が存在することを示し，その $p$ について $a^p\leqq f(n)^k<a^{p+1}$ を示せ．
  \item $c=\log_2 a$ とおく．すべての正の整数 $n$ に対して $f(n)=n^c$ であることを示せ．
  \item $f(3)=27$ であるとき，$f(12)$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $p$ を素数とする．すべての自然数 $n$ に対して $n^p-n$ が $p$ で割り切れることを，$n$ に関する数学的帰納法で示せ．
  \item すべての自然数 $n$ に対して，$n^{13}-n$ は $2730$ で割り切れることを示せ．
  \item すべての自然数 $n$ に対して $n^{13}-n$ を割り切る自然数のうち最大のものを求めよ．
\end{enumerate}

$p$ を素数とする．整数係数の多項式 $F(x),\ G(x)$ について，$F(x)-G(x)$ のすべての係数が $p$ の倍数であるとき $F(x)\equiv G(x)\pmod p$ と書く．また，2以上の整数 $n$ に対し，${}_n\mathrm{C}_1,\ \cdots,\ {}_n\mathrm{C}_{n-1}$ の最大公約数を $D_n$ とする．
\begin{enumerate}
  \item 正の整数 $e,\ m$ に対し，$(1+x)^{p^em}\equiv(1+x^{p^e})^m\pmod p$ を示せ．
  \item $n$ が相異なる2つ以上の素因数をもつとき，$D_n=1$ を示せ．
  \item $n=p^e$（$e$ は正の整数）のとき，$D_n=p$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item すべての自然数 $n$ は，0以上の整数 $a$ と3で割り切れない自然数 $m$ を用いて $n=3^am$ と表せることを，累積帰納法（$n$ より小さいすべての自然数で成り立てば $n$ でも成り立つことを示す形）で証明せよ．また，この表し方はただ1通りであることを示せ．
  \item $N$ を自然数とする．1から $3N$ までの自然数からどのように $2N+1$ 個を選んでも，その中に一方が他方の $3^j$ 倍（$j$ は正の整数）となる2数が存在することを示せ．
  \item (2) の「$2N+1$ 個」を「$2N$ 個」に置き換えると，主張は成り立たないことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $n$ を正の整数とする．$7^{2^n}-1$ は $2^{n+3}$ で割り切れるが，$2^{n+4}$ では割り切れないことを示せ．
  \item $7^m-1$ が $2^m$ で割り切れるような正の整数 $m$ をすべて求めよ．
  \item $7^m-1$ が $2^{20}$ で割り切れるような最小の正の整数 $m$ を求めよ．
\end{enumerate}

$xy$ 平面上で，$m,n$ が整数で $m+n$ が偶数であるような点 $(m,n)$ をすべて考え，それぞれを中心として半径 $r$ の円をかく．
\begin{enumerate}
  \item 傾き $\dfrac25$ の任意の直線がこれらの円のどれかと共有点をもつような $r$ の最小値を求めよ．
  \item 傾き $\dfrac35$ の任意の直線がこれらの円のどれかと共有点をもつような $r$ の最小値を求めよ．
\end{enumerate}

$m,\ n$ を正の整数とする．
\begin{enumerate}
  \item $m^n+1$ と $n^m+1$ がともに10の倍数となるための，$m,\ n$ についての必要十分条件を求めよ．
  \item $m^n+1$ と $n^m+1$ がともに100の倍数となるための，$m,\ n$ についての必要十分条件を求めよ．
  \item (2)の条件をみたし $m<n$ であるもののうち，$m+n$ が最小となる組 $(m,n)$ を求めよ．
\end{enumerate}

正の整数 $n$ の正の約数の総和を $\sigma(n)$ で表す．$\sigma(n)=2n$ をみたす $n$ を完全数という．
\begin{enumerate}
  \item $n=2^a\cdot3\cdot p$（$a$ は正の整数，$p$ は5以上の素数）の形の数で $\sigma(n)=3n$ をみたすものをすべて求めよ．
  \item 偶数 $n$ が完全数ならば，$2^{k+1}-1$ が素数となる正の整数 $k$ を用いて $n=2^k(2^{k+1}-1)$ と表されることを示せ．
  \item 6でない偶数の完全数を9で割った余りは1であることを示せ．
\end{enumerate}

正の整数 $a$ について，次の条件(P)を考える．
\begin{center}
(P)\quad $2a$ はある正の整数の3乗であり，$7a$ はある正の整数の5乗である．
\end{center}
\begin{enumerate}
  \item (P)をみたし，どんな2以上の整数 $d$ についても $d^{15}$ で割り切れない $a$ を求めよ．
  \item (P)をみたす $a$ 全体を，(1)の $a$ を用いて表せ．
  \item (P)をみたし，さらに $a$ 自身が平方数であるような最小の $a$ を素因数分解の形で求めよ．
\end{enumerate}

正の整数 $x$ が2で割り切れる回数を $v_2(x)$ で表す．$2023=(11111100111)_2$ である．
\begin{enumerate}
  \item $0\leqq m\leqq n$ のとき，$v_2({}_n\mathrm C_m)$ は，$m$ を $2^i$ で割った余りが $n$ を $2^i$ で割った余りより大きくなるような正の整数 $i$ の個数に等しいことを示せ．
  \item ${}_{2023}\mathrm C_m$（$m=0,1,\dots,2023$）のうち奇数であるものの個数を求めよ．
  \item ${}_{2023}\mathrm C_m$ が8の倍数となる最小の $m$，16の倍数となる最小の $m$ をそれぞれ求めよ．
\end{enumerate}

\begin{enumerate}
  \item $2^n=k^3+8$ をみたす正の整数の組 $(k,n)$ をすべて求めよ．
  \item $2^n+65=k^2$ をみたす正の整数の組 $(k,n)$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 素数 $p$ と $1\leqq k\leqq p-1$ に対して ${}_p\mathrm C_k$ は $p$ の倍数であることを示し，これを用いて，すべての正の整数 $a$ に対して $a^p-a$ が $p$ で割り切れることを数学的帰納法で示せ．
  \item すべての整数 $n$ に対して $n^{13}-n$ は2730で割り切れることを示せ．
  \item すべての整数 $n$ に対して $n^{13}-n$ を割り切る正の整数のうち最大のものを求めよ．
\end{enumerate}

$n$ を正の整数とする．
\begin{enumerate}
  \item $n(n+1)(n+2)(n+3)+1$ は平方数であることを示せ．
  \item $n(n+1)(n+2)(n+3)$ は平方数でないことを示せ．
  \item 連続する3つの正の奇数の積 $(2n-1)(2n+1)(2n+3)$ は，どんな2以上の整数 $k$ についても，正の整数の $k$ 乗にならないことを示せ．
\end{enumerate}

正の整数 $a$ に対して $d(a)$ を $a^2+1$ と $(3a+1)^4+1$ の最大公約数とする．
\begin{enumerate}
  \item $(3a+1)^4+1$ を $a$ の多項式とみて $a^2+1$ で割った余りを求めよ．
  \item $d(a)$ のとりうる値をすべて求めよ．
  \item $d(a)$ が最大となる最小の正の整数 $a$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 正の整数 $x,\ y$ を用いて $23x+37y$ と表せない正の整数のうち，最大のものを求めよ．
  \item 正の整数 $x,\ y$ を用いて $23x+37y$ と表せない正の整数の個数を求めよ．
  \item $23x+37y=2026$ をみたす正の整数の組 $(x,y)$ をすべて求めよ．
