\begin{enumerate}
  \item $2^{2025}+1$ を2025で割った余りを求めよ．
  \item $2^n+1$ が2025の倍数となる正の整数 $n$ は存在しないことを示せ．
  \item $2^n-1$ が2025の倍数となる最小の正の整数 $n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 正の整数 $n$ が $n=ab$（$a,\ b$ は整数で $3\leqq a<b$）と表されるとき，$(n-1)!$ は $n^2$ で割り切れることを示せ．
  \item $n!$ が $n^3$ で割り切れないような2以上の整数 $n$ をすべて決定せよ．
  \item $2\leqq n\leqq100$ のうち，$n!$ が $n^3$ で割り切れない $n$ の個数を求めよ．
\end{enumerate}

$a,\ b$ を互いに素な2以上の整数とする．
\begin{enumerate}
  \item $b,\ 2b,\ \dots,\ (a-1)b$ を $a$ で割った余りは，$1,2,\dots,a-1$ を並べかえたものであることを示せ．また，$kb-\ell a=1$ をみたす整数 $k,\ \ell$ が存在することを示せ．
  \item $\displaystyle\sum_{k=1}^{a-1}\left\lfloor\frac{kb}a\right\rfloor=\frac{(a-1)(b-1)}2$ を示せ．ただし $\lfloor x\rfloor$ は $x$ を超えない最大の整数である．
  \item $\displaystyle\sum_{k=1}^{2026}\left\lfloor\frac{1000k}{2027}\right\rfloor$ の値を求めよ．
\end{enumerate}

実数 $a,\ b,\ c,\ d$ に対して $f(x)=ax^3+bx^2+cx+d$ とする．
\begin{enumerate}
