$n$ が $d$ 桁のとき $10^{d-1}\leqq n$，$S(n)\leqq9d$．また $10^j\equiv1\pmod9$ より $n\equiv S(n)\pmod9$ である．

(1) $s=S(n)$ とする．$10^{d-1}\leqq n=s^3\leqq729d^3$．$d=7$ では $729\cdot343=250047<10^6$．$729d^3<10^{d-1}$ が成り立てば $729(d+1)^3=729d^3\left(1+\frac1d\right)^3<10^{d-1}\cdot\left(\frac87\right)^3<10^{d}$（$d\geqq7$）なので，$d\geqq7$ ではつねに $729d^3<10^{d-1}$ となり矛盾．よって $d\leqq6$，$1\leqq s\leqq54$．

$s\equiv s^3\pmod9$ より $(s-1)s(s+1)$ は9の倍数．連続する3整数のうち3の倍数はちょうど1つなので，その1つが9の倍数でなければならず，$s\equiv0,1,8\pmod9$．$1\leqq s\leqq54$ の候補について $s^3$ と $S(s^3)$ を調べる．
\begin{center}
\begin{tabular}{c|cccccccccc}
$s$ & 1 & 8 & 9 & 10 & 17 & 18 & 19 & 26 & 27 & 28\\ \hline
$s^3$ & 1 & 512 & 729 & 1000 & 4913 & 5832 & 6859 & 17576 & 19683 & 21952\\
$S(s^3)$ & 1 & 8 & 18 & 1 & 17 & 18 & 28 & 26 & 27 & 19
\end{tabular}

\vspace{2mm}
\begin{tabular}{c|cccccccc}
$s$ & 35 & 36 & 37 & 44 & 45 & 46 & 53 & 54\\ \hline
$s^3$ & 42875 & 46656 & 50653 & 85184 & 91125 & 97336 & 148877 & 157464\\
$S(s^3)$ & 26 & 27 & 19 & 26 & 18 & 28 & 35 & 27
\end{tabular}
\end{center}
$S(s^3)=s$ となるのは $s=1,8,17,18,26,27$．よって $\boldsymbol{n=1,\ 512,\ 4913,\ 5832,\ 17576,\ 19683}$．

(2) $s=S(n)$ とする．$n\geqq2026$ より $d\geqq4$．$d\geqq5$ と仮定すると $10^{d-1}\leqq n=3s^2+2026\leqq243d^2+2026$．$d=5$ では右辺 $=8101<10^4$．$243d^2+2026<10^{d-1}$ が成り立てば $243(d+1)^2+2026\leqq4(243d^2)+2026<10(243d^2+2026)<10^d$ なので，$d\geqq5$ ではつねに矛盾．よって $d=4$，$s\leqq36$，$n\leqq3\cdot36^2+2026=5914$．千の位は5以下なので $s\leqq5+9+9+9=32$．

$2026=9\cdot225+1$ より $s\equiv3s^2+1\pmod9$，すなわち $3s^2-s+1\equiv0\pmod9$．3を法として $-s+1\equiv0$ なので $s=3m+1$ とおける．代入すると
\[
3(3m+1)^2-(3m+1)+1=27m^2+15m+3\equiv6m+3\pmod9
\]
で，$6m+3\equiv0\pmod9\iff2m+1\equiv0\pmod3\iff m\equiv1\pmod3$．よって $s\equiv4\pmod9$，$s\leqq32$ から $s=4,13,22,31$．
\begin{center}
\begin{tabular}{c|cccc}
$s$ & 4 & 13 & 22 & 31\\ \hline
$3s^2+2026$ & 2074 & 2533 & 3478 & 4909\\
各位の和 & 13 & 13 & 22 & 22
\end{tabular}
\end{center}
条件をみたすのは $s=13,22$ で，$\boldsymbol{n=2533,\ 3478}$．

statement.tex:
\begin{enumerate}
  \item 各位の数の和が3である100桁の正の整数のうち，2020で割り切れるものは存在しないことを示せ．
  \item 各位の数の和が4である100桁の正の整数のうち，2020で割り切れるものの個数を求めよ．
\end{enumerate}

以下の問いに答えよ．ただし，実数 $x$ に対し $[x]$ は $x$ を超えない最大の整数を表す．
\begin{enumerate}
  \item $p$ を素数，$N$ を自然数とする．$N!$ を割り切る $p$ のべき $p^e$ のうち最大のものの指数 $e$ は $\displaystyle\sum_{j=1}^{J}\left[\frac N{p^j}\right]$ に等しいことを示せ．ただし $J$ は $p^J\leqq N$ をみたす最大の整数とする（$p>N$ のときは $e=0$ とする）．
  \item $n\geqq2$，$1\leqq k\leqq n-1$ とする．素数 $p$ と0以上の整数 $e$ について，$p^e$ が ${}_n\mathrm C_k$ を割り切るならば $p^e\leqq n$ であることを示せ．
  \item 0以上の整数 $k,n$（$k\leqq n$）で，${}_n\mathrm C_k$ がある素数 $p$ と自然数 $a$ を用いて $p^a$ と表されるような組 $(n,k)$ をすべて求めよ．
\end{enumerate}

座標平面上の楕円 $E:\ x^2+2y^2=1$ を考える．$n$ を2以上の整数とし，$k=1,2,\cdots,n-1$ に対して，$E$ 上の点で $x$ 座標が $\dfrac kn$，$y$ 座標が正であるものを $\mathrm B_k$ とする．$\mathrm B_k$ から $x$ 軸，$y$ 軸に下ろした垂線の足をそれぞれ $\mathrm A_k$，$\mathrm C_k$ とし，線分 $\mathrm A_k\mathrm B_k$ と線分 $\mathrm B_k\mathrm C_k$ のうち短い方の長さ（等しいときはその共通の長さ）を $L_n(k)$ とする．
\begin{enumerate}
  \item $L_n(k)$ $(k=1,2,\cdots,n-1)$ を最大にする $k$ がちょうど2個存在するための必要十分条件は，$n^2=3m^2+2m+1$ をみたす正の整数 $m$ が存在することであり，そのとき最大にする $k$ は $m$ と $m+1$ であることを示せ．
  \item $L_n(k)$ を最大にする $k$ がちょうど2個存在するような $n$ のうち，$n\leqq3000$ であるものをすべて求めよ．
  \item $L_n(k)$ を最大にする $k$ がちょうど2個存在するような $n$ を小さい方から順に $n_1,n_2,n_3,\cdots$ とし，$n=n_j$ のとき最大にする2つの $k$ のうち小さい方を $k_j$ とする．$k_{j+1}$，$n_{j+1}$ をそれぞれ $k_j$，$n_j$ の1次式で表せ．
\end{enumerate}

$m$ は3以上の奇数で，素数ではないとする．$m$ の正の約数のうち 1 と $m$ 以外のものを小さい順に $d_1<d_2<\dots<d_s$ とし，条件
\begin{center}
（＊）\quad $d_s-d_1\leqq6$
\end{center}
を考える．
\begin{enumerate}
  \item 条件（＊）をみたす $m$ は，ある奇素数 $p$ を用いて
  \[m=p^2,\quad m=p(p+2),\quad m=p(p+4),\quad m=p(p+6)\]
  （ただし後の3つでは $p+2,\ p+4,\ p+6$ もそれぞれ素数）のいずれかで表されるか，または $m=27$ であることを示せ．また，逆にこれらはすべて条件（＊）をみたすことを示せ．
  \item 条件（＊）をみたす $m$ のうち $s=1$ となるものについて，$p=d_1$ とおく．正の整数 $n$ に対し，$(pn+1)^p-1$ が $mp$ の倍数となるための $n$ の条件を求めよ．
\end{enumerate}

正の実数 $a,b,c$ を係数とする2次式 $f(x)=ax^2+bx+c$ について，次の条件Dを考える．
\begin{center}
条件D：すべての整数 $n$ について $f(n^2)$ が整数となる．
\end{center}
\begin{enumerate}
  \item $f(x)$ が条件Dをみたすとき，$12a$ は整数であることを示せ．
  \item $f(0)$，$f(1)$，$f(4)$ がすべて整数ならば，$f(x)$ は条件Dをみたすことを示せ．
  \item 条件Dをみたし $f(1)=2$ となる $f(x)$ のうち，$a$ が最小となるものを求めよ．
  \item $N$ を自然数とする．条件Dをみたし $f(1)=N$ となる $f(x)$ の個数を $N$ で表せ．
\end{enumerate}

\begin{enumerate}
  \item 6以上の整数 $n$ に対して $2^n>n^2+n+2$ が成り立つことを数学的帰納法により示せ．
  \item 等式 $p^q-q^p=p+q$ をみたす素数の組 $(p,q)$ をすべて求めよ．
\end{enumerate}

$n$ を2以上の整数とし，正の整数 $e$ に対して，$1\leqq k\leqq n$ をみたす整数 $k$ のうち $k^e-1$ が $n$ で割り切れるものの個数を $N_e(n)$ とする．
\begin{enumerate}
  \item $N_3(n)$ は奇数であることを示せ．
  \item $n$ が $8$ の倍数ならば，$N_2(n)$ は $4$ の倍数であることを示せ．
  \item $m$ を3以上の整数とする．$N_2(2^m)$ を求めよ．
\end{enumerate}

$c$ を正の実数とする．
\begin{enumerate}
  \item 次の命題 (A) が成り立つための，$c$ についての必要十分条件を求めよ．
  \begin{center}
  (A)：2以上の任意の整数 $n$ に対し，ある自然数 $m$ が存在して $n^3<m^2<n^3+cn\sqrt n$ が成り立つ．
  \end{center}
  \item 次の命題 (B) が成り立つための，$c$ についての必要十分条件を求めよ．
  \begin{center}
  (B)：2以上の任意の整数 $n$ に対し，ある自然数 $m$ が存在して $n^3-cn\sqrt n<m^2<n^3$ が成り立つ．
  \end{center}
\end{enumerate}

$p$ を素数とする．$0$ 以上の整数 $N,\ i$ に対し，$N<i$ のときは ${}_N\mathrm C_i=0$ と定める．
\begin{enumerate}
  \item $k\geqq0$，$0\leqq r\leqq p-1$，$1\leqq i\leqq p-1$ をみたす整数 $k,r,i$ に対して，${}_{kp+r}\mathrm C_i-{}_r\mathrm C_i$ は $p$ の倍数であることを示せ．
  \item $k\geqq0$，$0\leqq r\leqq p-1$ をみたす整数 $k,r$ に対して，${}_{kp+r}\mathrm C_p-k\cdot{}_{p+r}\mathrm C_p$ は $p^2$ の倍数であることを示せ．
  \item $a$ を整数とする．$0\leqq n\leqq p^3-1$ をみたす整数 $n$ のうち，${}_n\mathrm C_p-a$ が $p^2$ の倍数となるものの個数を求めよ．
\end{enumerate}

正の整数 $m$ に対し，$m$ の正の約数の個数を $d(m)$ で表す．
\begin{enumerate}
  \item $d(n^3)=n$ をみたす正の整数 $n$ は3の倍数でないことを示せ．
  \item $d(n^3)=n$ をみたす正の整数 $n$ をすべて求めよ．
\end{enumerate}

2以上の整数 $N$ に対し，$N!$ を素因数分解したときの素数 $p$ の指数を $e_p$ とする（$p>N$ なら $e_p=0$）．正の整数の組 $(a,b,c)$ で
\begin{center}
「$a$ と $b$，$b$ と $c$，$c$ と $a$ はどれも互いに素で，$abc$ は $N!$ の約数である」
\end{center}
をみたすものを考える．
\begin{enumerate}
  \item $N=10$ のとき，このような組 $(a,b,c)$ の個数を求めよ．
  \item $N=10$ のとき，このような組 $(a,b,c)$ のうち $a\leqq b\leqq c$ をみたすものの個数を求めよ．
  \item 一般の $N$ について，$N$ 以下の素数を $p_1,p_2,\dots,p_m$ とし，
  \[P=(3e_{p_1}+1)(3e_{p_2}+1)\cdots(3e_{p_m}+1),\qquad Q=(e_{p_1}+1)(e_{p_2}+1)\cdots(e_{p_m}+1)\]
  とおく．このような組 $(a,b,c)$ のうち $a\leqq b\leqq c$ をみたすものの個数を $P,\ Q$ で表せ．
\end{enumerate}

$m,n$ を正の整数とする．$\dfrac{m^3-mn+2}{m^2+mn+1}$ が整数となるとき，その値を $k$ とする．
\begin{enumerate}
  \item $k\geqq0$ であり，$2-k$ は $m$ の倍数であることを示せ．
  \item $\dfrac{m^3-mn+2}{m^2+mn+1}$ が整数となるような正の整数の組 $(m,n)$ をすべて求めよ．
\end{enumerate}

$n$ を2以上の整数とする．$1,\ 2,\ \cdots,\ n$ を1列に並べた順列 $p=(p_1,\ p_2,\ \cdots,\ p_n)$ 全体（$n!$ 個）を辞書式に小さい順に並べ，最初のものを0番，次のものを1番，$\cdots$，最後のものを $(n!-1)$ 番とする．ここで辞書式とは，2つの順列を，はじめて異なる位置にある数の大小で比べる順序のことである．順列 $p$ の番号を $N(p)$ とおく．また，$1\leqq k\leqq n$ に対し，$p_{k+1},\ \cdots,\ p_n$ のうち $p_k$ より小さいものの個数を $c_k$ とする（$c_n=0$ とする）．
\begin{enumerate}
  \item $N(p)=\displaystyle\sum_{k=1}^{n-1}c_k\cdot(n-k)!$ が成り立つことを示せ．
  \item $n=7$ のとき，$N(p)=2025$ となる順列 $p$ を求めよ．
  \item $n\geqq4$ とする．$N(p)$ が8の倍数であるための必要十分条件を，4つの数 $p_{n-3},\ p_{n-2},\ p_{n-1},\ p_n$ の大小関係として求めよ．
\end{enumerate}

$m$ を正の整数とする．
\begin{enumerate}
  \item $a$ を整数，$p$ を奇数の素数とし，$a^{2^m}+1$ は $p$ の倍数であるとする．$a^l-1$ が $p$ の倍数となる正の整数 $l$ のうち最小のものを $k$ とする．$k=2^{m+1}$ であることを示し，さらに $p-1$ は $2^{m+1}$ の倍数であることを示せ．
  \item $2^{m+1}$ で割って1余る素数は無数に存在することを示せ．
  \item $2^{32}+1$ の素因数のうち最小のものを求めよ．
\end{enumerate}

$p,\ q$ を奇数とし，$x$ の2次方程式 $x^2-px+q=0$ が異なる2つの実数解 $\alpha,\ \beta$（$\alpha<\beta$）をもつとする．実数 $x$ に対し，$x$ を超えない最大の整数を $[x]$ で表す．
\begin{enumerate}
  \item $\alpha,\ \beta$ はともに無理数であり，$[\alpha]+[\beta]=p-1$ が成り立つことを示せ．
  \item $n$ を正の整数とし，$p=2n+1$ とする．方程式が異なる2つの実数解をもつような正の奇数 $q$ のすべてについて $[\alpha]$ を加えた和 $S_n$ を求めよ．
  \item (2) と同じ $q$ のすべてについて $[\alpha][\beta]$ を加えた和 $U_n$ を求めよ．
\end{enumerate}

3辺の長さ，内接円の半径 $r$，外接円の半径 $R$ がすべて整数であるような二等辺三角形を考える．等しい2辺の長さを $b$，残りの辺（底辺）の長さを $c$ とする（正三角形はこの条件をみたさないことが後でわかる）．
\begin{enumerate}
  \item $c$ は偶数であり，底辺に下ろした高さ $h$ も整数であることを示せ．
  \item $R$ のとりうる値の最小値と，そのときの三角形の3辺の長さの組をすべて求めよ．
\end{enumerate}

正の整数 $m$，$n$（$m\leqq n$）に対して
\[
T_{m,n}=\sum_{k=m}^{n}\frac1{3k-1}=\frac1{3m-1}+\frac1{3m+2}+\cdots+\frac1{3n-1}
\]
とおく．
\begin{enumerate}
  \item 正の整数 $e$ に対し，$3k-1$（$k$ は正の整数）の形の数のうち $2^e$ で割り切れる最小のものを $e$ を用いて表せ．
  \item $m<n$ のとき，$T_{m,n}$ は整数でないことを示せ．
  \item $T_{1,n}$ を既約分数で表したときの分母は，$2^g$ で割り切れ $2^{g+1}$ で割り切れないとする（$g$ は0以上の整数）．$g$ は常に奇数であることを示せ．また，$g=7$ となる $n$ の範囲を求めよ．
\end{enumerate}

$p,\ q$ を正の奇数とし，$\alpha=\dfrac{p+q\sqrt5}{2}$ とおく．正の整数 $n$ に対し，有理数 $a_n,\ b_n$ を $\alpha^n=a_n+b_n\sqrt5$ により定める．
\begin{enumerate}
  \item $m=\dfrac{p^2-5q^2}{4}$ は奇数の整数であることを示し，$\alpha^2=p\alpha-m$ が成り立つことを示せ．
  \item $a_n,\ b_n$ がともに整数となるような正の整数 $n$ をすべて求めよ．
  \item $n$ が (2) で求めたもの以外のとき，$2a_n,\ 2b_n$ はともに奇数であることを示せ．
\end{enumerate}

$xy$ 平面上の2点 $\mathrm A(-3,0)$，$\mathrm B(3,0)$ を考える．$x$ 座標も $y$ 座標も正の整数であり，A，B からの距離がともに整数であるような点 P 全体の集合を $K$ とする．
\begin{enumerate}
  \item $K$ に属する点 P に対して，$\mathrm{PA}-\mathrm{PB}$ は2または4であることを示せ．
  \item $K$ は無限集合であることを示せ．
  \item $K$ に属する点 P で $\mathrm{PA}-\mathrm{PB}=4$ となるもののうち，$x$ 座標が最小のものを求めよ．
\end{enumerate}

正の整数 $n$ に対し，$n=\displaystyle\sum_{j=0}^{k}a_j\cdot2^j$ をみたすように0以上の整数 $k$ と整数 $a_0,\dots,a_k$ を動かすときの $\displaystyle\sum_{j=0}^{k}|a_j|$ の最小値を $b_n$ とおく．
\begin{enumerate}
  \item 正の整数 $k$ に対し，$b_n=k$ となる最小の正の整数 $n$ を $k$ で表せ．
  \item 正の整数 $m$ に対し，$1\leqq n\leqq2^m$ における $b_n$ の最大値を $m$ で表せ．
  \item 正の整数 $m$ に対し，$1\leqq n\leqq2^m$ かつ $b_n=2$ をみたす $n$ の個数を $m$ で表せ．
\end{enumerate}

内側が鏡になっている長方形 ABCD があり，$\mathrm{AB}=126$，$\mathrm{BC}=105$ である．辺 AB 上に $\mathrm{AP}=5$ となる点 P をとり，P から長方形の内部に向けて，B の側に傾いた向きで，辺 AB とのなす角 $\theta$ が $\tan\theta=2$ をみたすように光を発射する．光は長方形の内部を直進し，辺に当たると入射角と反射角が等しくなるように反射する．
\begin{enumerate}
  \item 光は長方形の頂点に当たることなく再び P に到達することを示せ．また，発射してから初めて P に到達するまでに光が辺で反射する回数を求めよ．
  \item 発射してから初めて P に到達するまでの光の道筋を考える．長方形の内部（周を除く）で，この道筋が自分自身と交わる点の個数を求めよ．
\end{enumerate}

$n$ を $3$ 以上の整数とする．$n$ 個の正の整数からなる集合 $S$ が次の条件をみたすとする．
\begin{center}
$S$ の相異なる3つの要素 $x,\ y,\ z$ をどのように選んでも，$y$ と $z$ の最小公倍数は $x$ で割り切れる．
\end{center}
$S$ の全要素の最小公倍数を $L$ とし，$x\in S$ に対して $d_x=\dfrac{L}{x}$ とおく．また，$k$ 番目に小さい素数を $p_k$ とする（$p_1=2$，$p_2=3$，$p_3=5,\ \dots$）．
\begin{enumerate}
  \item $S$ の相異なる2要素 $x,\ y$ について，$d_x$ と $d_y$ は互いに素であることを示せ．
  \item $S$ の最大の要素としてありうる最小の値を $n$ で表せ．
  \item $S$ の要素がすべて $1000$ 以下であるとき，$n$ の最大値を求めよ．また，$n$ がその最大値となるような集合 $S$ は何個あるか．
\end{enumerate}

4 が $a$ 個，6 が $b$ 個，9 が $c$ 個ある（$a,\ b,\ c$ は0以上の整数で，$a+b+c\geqq1$）．これらのうちから1個以上をとって掛け合わせることによってできる相異なる数の個数を $f(a,\ b,\ c)$ とする．
\begin{enumerate}
  \item $b\geqq1$ のとき，$f(a,\ b,\ c)=ab+bc+2ca+a+b+c$ を示せ．
  \item $n$ を2以上の整数とする．$a+b+c=n$ のとき，$f(a,\ b,\ c)$ の最大値を求めよ．
\end{enumerate}

図のような $3\times3$ のマス目の各マスに相異なる自然数を書き込み，各行・各列・2本の対角線のそれぞれに並ぶ3数の積がすべて等しくなるようにする．書き込まれた9数のうち最大のものを $M$ とする．
\begin{center}
$\begin{array}{|c|c|c|}\hline a&b&c\\\hline d&e&f\\\hline g&h&i\\\hline\end{array}$
\end{center}
\begin{enumerate}
  \item 共通の積は $e^3$ であることを示せ．
  \item $M$ の最小値 $M_0$ を求めよ．
  \item $M=M_0$ となる書き込み方は何通りあるか．ただし，回転・裏返しによる同一視はしない．
\end{enumerate}

有理数に対して定義され，0以上の実数値をとる関数 $f$ で，次の3条件をみたすものをすべて求めよ．
\begin{itemize}
  \item 任意の有理数 $x,\ y$ に対して $f(xy)=f(x)f(y)$
  \item 任意の有理数 $x,\ y$ に対して $f(x+y)\leqq f(x)+f(y)$
  \item $f(2)=\dfrac12$
\end{itemize}

\begin{enumerate}
  \item $k$ を自然数とする．各桁の数字が $0$ か $1$ で，$1$ がちょうど $k$ 個あり，$k$ の倍数であるような自然数 $n$ で，桁数が $k^2-k+1$ 以下のものが存在することを示せ．
  \item $k=11$ のとき，(1) の条件のうち桁数の制限を除いた条件（各桁は0か1，1がちょうど11個，11の倍数）をみたす最小の自然数を求めよ．
\end{enumerate}

$a,b$ を2以上の互いに素な自然数とする．$0$ 以上の整数 $x,y$ を用いて $ax+by$ の形に表されない自然数全体の集合を $E$ とする．
\begin{enumerate}
  \item $1\leqq r\leqq a-1$ とする．$a$ で割った余りが $rb$ を $a$ で割った余りと等しい自然数のうち，$ax+by$ の形に表されるものの最小値は $rb$ であることを示せ．
  \item $E$ の要素の総和を $a,b$ で表せ．
\end{enumerate}

$k$ を自然数とする．自然数を要素とする有限集合 $T$（要素は2個以上）が，
\begin{center}
どの異なる2つの要素 $x,y$ をとっても，$|x-y|$ が $x$ と $y$ の最大公約数の $k$ 倍に等しい
\end{center}
という条件をみたすとき，$T$ を「$k$-集合」とよぶ．
\begin{enumerate}
  \item 3個の要素からなる2-集合は存在しないことを示せ．
  \item 3個の要素からなる3-集合の例を1つ挙げよ．
  \item 4個の要素からなる3-集合は存在しないことを示せ．
\end{enumerate}

自然数 $n$ を3進法で表したときの各桁の数字の和を $s(n)$ とする．
\begin{enumerate}
  \item $n!$ を素因数分解したときの素因数3の個数は $\dfrac{n-s(n)}{2}$ であることを証明せよ．
  \item ${}_{2n}\mathrm C_n$ を素因数分解したときの素因数3の個数は，3進法で $n+n$ を筆算したときに起こる繰り上がりの回数に等しいことを証明せよ．
  \item $m$ を自然数とする．$1\leqq n\leqq3^m-1$ をみたす整数 $n$ のうち，${}_{2n}\mathrm C_n$ が3で割り切れないものの個数を求めよ．
\end{enumerate}

$n$ を2以上の整数とし，$n$ の正の約数を小さい順に $d_1,d_2,\dots,d_k$ とする．$D=\displaystyle\sum_{i=1}^{k-1}d_id_{i+1}$ とおく．
\begin{enumerate}
  \item $D<n^2$ を示せ．
  \item $n^2$ が $D$ で割り切れるような $n$ をすべて求めよ．
\end{enumerate}

2以上の整数 $a$ に対し $n=2^a$ とする．ここで「2のべき」とは $2^b$（$b$ は0以上の整数）の形の数のことである．
\begin{enumerate}
  \item $n$ が2桁以上で，上から2番目の桁の数字が0でなく，$n$ の最高位の数字を取り除いて得られる整数が2のべきであるような $n$ をすべて求めよ．
  \item $n$ が3桁以上で，上から3番目の桁の数字が0でなく，$n$ の上位2桁の数字を取り除いて得られる整数が2のべきであるような $n$ をすべて求めよ．
\end{enumerate}

3以上の整数 $n$ に対し，集合 $S_n$ を次のように定める．
\begin{center}
黒板に1から $n$ までの整数が1つずつ書かれている．このうちちょうど2つを消したとき，残った整数の平均としてありうる数の集合を $S_n$ とする．
\end{center}
$3\leqq n<m$ をみたす整数 $n,m$ に対し，$S_n\cap S_m$ の要素の個数を求めよ．

数列 $\{a_n\}$ を $a_1=2,\ a_2=6,\ a_{n+2}=2a_{n+1}+a_n\ (n\geqq1)$ で定める．
\begin{enumerate}
  \item $p$ が素数，$m$ が正の整数で，$a_{2m}-2$ が $p$ の倍数ならば，$a_{2m+1}-2$ も $p$ の倍数であることを示せ．
  \item (1) の逆，すなわち「$a_{2m+1}-2$ が $p$ の倍数ならば $a_{2m}-2$ も $p$ の倍数」はつねに成り立つか．
\end{enumerate}

次の条件をみたす奇数 $N$ のうち最小のものを求めよ．
\begin{center}
（条件）$N$ の正の約数（1 と $N$ を含む）はちょうど12個あり，それらを13で割った余りは $1,2,\dots,12$ が1つずつである．
\end{center}

線分 AB がある．3点 P，Q，R は A から同時に出発し，AB 間を一定の速さで往復し続ける．P，Q，R は片道をそれぞれ $p$ 秒，$q$ 秒，$r$ 秒で進む．$p,q,r$ はどの2つも互いに素な奇数とする．
\begin{enumerate}
  \item 出発してから $2pq$ 秒間のうちで，P と Q が同じ向きに進んでいる時間は，異なる向きに進んでいる時間よりも2秒多いことを示せ．
  \item 出発してから $2pqr$ 秒間のうちで，P，Q，R の3点がすべて同じ向きに進んでいる時間の合計を求めよ．
\end{enumerate}

$p$ を素数とする．以下，$[x]$ は $x$ を超えない最大の整数を表す．
\begin{enumerate}
  \item $n,\ k$ を $1\leqq k\leqq n-1$ をみたす整数とし，${}_n\mathrm C_k$ が $p^e$ で割り切れ $p^{e+1}$ で割り切れないとする（$e\geqq0$）．このとき $p^e\leqq n$ であることを示せ．
  \item $m$ を正の整数とする．$1\leqq k\leqq n-1$ かつ ${}_n\mathrm C_k=p^m$ となる整数の組 $(n,k)$ をすべて求めよ．
  \item $p$ は奇数の素数，$m$ は正の整数とする．$1\leqq k\leqq n-1$ かつ ${}_n\mathrm C_k=2p^m$ となる整数の組 $(n,k)$ をすべて求めよ．
\end{enumerate}

数列 $\{a_n\}$ において，$a_1=2$ であり，$n\geqq2$ に対して $a_n$ は次の条件 (i)，(ii) をみたす2以上の整数のうち最小のものであるという．
\begin{itemize}
  \item[(i)] $a_n$ は $a_1,\dots,a_{n-1}$ のどの項とも異なる．
  \item[(ii)] $a_1,\dots,a_{n-1}$ のうちから重複なく2個以上の項をどのように取り出しても，それらの積が $a_n$ に等しくなることはない．
\end{itemize}
\begin{enumerate}
  \item $a_1$ から $a_{10}$ までを求めよ．
  \item 素数 $p$ と0以上の整数 $k$ を用いて $p^{2^k}$ と表される数全体を小さい順に並べた数列を $\{s_n\}$ とする．すべての $n$ について $a_n=s_n$ であることを示せ．
  \item $a_{31}$ を求めよ．また，$256$ は数列 $\{a_n\}$ の第何項か．
\end{enumerate}

\begin{enumerate}
  \item $x^6+y^4=7z^2$ をみたす正の整数 $x,y,z$ は存在しないことを示せ．
  \item $x^6+y^4=z^2$ をみたす正の整数 $x,y,z$ の組のうち，$z^2$ が最小となるものをすべて求めよ．また，そのときの $z^2$ の値を求めよ．
\end{enumerate}

座標平面上の点 $(x,y)$ について，$x,y$ がともに有理数であるとき，その点を有理点という．
\begin{enumerate}
  \item 曲線 $C:\ x^2-3y^2=1$ 上の点 A$(-1,0)$ と，A と異なる $C$ 上の点 P を考える．P が有理点であるための必要十分条件は，直線 AP の傾きが有理数であることを示せ．また，直線 AP の傾きが $m$ のときの P の座標を $m$ で表せ．
  \item $1\leqq k\leqq10$ をみたす整数 $k$ のうち，曲線 $x^2-3y^2=k$ 上に有理点が存在するものをすべて求めよ．
\end{enumerate}

直角三角形の斜辺の長さを $p$，他の2辺の長さを $q,r$ とし，$p,q,r$ はすべて自然数とする．
\begin{enumerate}
  \item $p,q,r$ のうち少なくとも2つが素数であるとする．このとき，素数であるのは $p$ と，$q,r$ のうちのちょうど一方であることを示せ．
  \item (1) の状況で，素数でない辺の長さは，3辺の長さの組が $\{3,4,5\}$，$\{5,12,13\}$ である場合を除き，$60$ の倍数であることを示せ．
  \item $p,q,r$ がいずれも「素数の正の整数乗」で表される数であるような $(p,q,r)$ をすべて求めよ．
\end{enumerate}

自然数 $n$ の正の約数（$1$ と $n$ 自身も含む）の個数を $f(n)$ とする．
\begin{enumerate}
  \item $f(n)^2=n$ をみたす自然数 $n$ をすべて求めよ．
  \item $f(n)^2\geqq n$ をみたす自然数 $n$ のうち最大のものを求めよ．
\end{enumerate}

\begin{enumerate}
  \item 球面 $x^2+y^2+z^2=7$ 上には，座標がすべて有理数である点は存在しないことを示せ．
  \item 球面 $T:\ x^2+y^2+z^2=3$ 上の点 $\mathrm N(1,1,1)$ と，$xy$ 平面上の点 $\mathrm Q(s,u,0)$（$s+u\neq3$）を通る直線は，$T$ と N 以外のただ1点 P で交わる．P の座標を $s,\ u$ で表せ．また，$s,\ u$ が有理数ならば P の座標はすべて有理数であることを示せ．
  \item $T$ 上の点で座標がすべて有理数であり，点 $\mathrm R(\sqrt3,0,0)$ との距離が $\dfrac1{1000}$ 未満であるものを1つ求めよ（距離が $\dfrac1{1000}$ 未満であることも示せ）．
\end{enumerate}

$n$ を2以上の整数とする．$k=1,2,\dots,n-1$ に対し，$\dfrac kn$ の小数第3位を四捨五入して小数第2位まで求めた値を $r_k$ とする．すなわち $r_k=\dfrac1{100}\left[\dfrac{100k}n+\dfrac12\right]$ である（$[\ \ ]$ はガウス記号）．
\begin{enumerate}
  \item $n\leqq100$ ならば $r_1,r_2,\dots,r_{n-1}$ はすべて異なることを示せ．
  \item $r_1,\dots,r_{n-1}$ の中に現れる値が，どれも同じ回数ずつ現れるような $n$ をすべて求めよ．
\end{enumerate}

公差が正の整数 $d$ である等差数列 $a_1,a_2,\cdots,a_n$ の項がすべて素数であるとき，これを項数 $n$，公差 $d$ の等差素数列という．
\begin{enumerate}
  \item $p$ を素数とする．$n\geqq p$ かつ $a_1>p$ である等差素数列の公差 $d$ は $p$ の倍数であることを示せ．
  \item 公差 12 の等差素数列の項数の最大値を求め，項数が最大となる公差 12 の等差素数列をすべて求めよ．
  \item 項数 6 の等差素数列のうち，第6項 $a_6$ が最小となるものを求めよ．
\end{enumerate}

集合 $S=\{\,4n^2+4n-1\mid n\text{ は自然数}\,\}$ を考える．$p$ を3以上の素数とし，$h=\dfrac{p-1}2$ とおく．また，実数 $x$ を超えない最大の整数を $[x]$ で表す．
\begin{enumerate}
  \item $t=h-\left[\dfrac h2\right]$ とおく．$2^h-(-1)^t$ は $p$ で割り切れることを示せ．
  \item $p$ が $S$ のある要素を割り切るならば，$p$ を8で割った余りは1または7であることを示せ．ただし，自然数 $m$ が $p$ で割り切れないとき $m^{p-1}-1$ が $p$ で割り切れること（フェルマーの小定理）は，証明して用いよ．
  \item 100 未満の素数で，$S$ のある要素を割り切るものをすべて求めよ．
\end{enumerate}

$p$ を素数とする．自然数 $m$ を，$p$ で割り切れない自然数 $c$ と0以上の整数 $e$ を用いて $m=cp^e$ と表すとき，$f_p(m)=p^{-e}$ と定める．また，実数 $u,\ v$ に対して $\max\{u,\ v\}$ は $u,\ v$ のうち小さくない方を表す．
\begin{enumerate}
  \item 自然数 $k,\ l$ が $f_p(k)\neq f_p(l)$ をみたすとき，$f_p(k+l)=\max\{f_p(k),\ f_p(l)\}$ であることを示せ．さらに $k>l$ ならば $f_p(k-l)=\max\{f_p(k),\ f_p(l)\}$ であることを示せ．
  \item $S_n=\displaystyle\sum_{i=1}^n3^{i-1}$ とおく．$\displaystyle\lim_{n\to\infty}f_3(aS_n+b)=0$ となる自然数の組 $(a,\ b)$ をすべて求めよ．
  \item $\displaystyle\lim_{n\to\infty}f_5(2^n+b)=0$ となる自然数 $b$ は存在しないことを示せ．
\end{enumerate}

自然数 $n$ に対し，$n$ を十進法で表したときの各桁の数字の和を $S(n)$ で表す．
\begin{enumerate}
  \item 自然数 $a,\ b$ に対し，$S(a+b)\leqq S(a)+S(b)$ および $S(ab)\leqq S(a)S(b)$ が成り立つことを示せ．
  \item $d=2^{10}$ とする．すべての自然数 $n$ について $S(dn)\geqq K\,S(n)$ が成り立つような正の実数 $K$ の最大値を求めよ．
  \item $d=7$ のときは，すべての自然数 $n$ について $S(7n)\geqq K\,S(n)$ が成り立つような正の実数 $K$ は存在しないことを示せ．
\end{enumerate}

$n$ を自然数とし，$n$ 個の相異なる素数 $p_1,\ p_2,\ \dots,\ p_n$ を決めておく．$f(x)$ を整数を係数とする次数1以上の多項式とする．
\begin{enumerate}
  \item 整数 $k$ で，$f(k)\neq0$ であり，かつ $f(k)$ が $p_1,\dots,p_n$ のいずれとも異なる素数で割り切れるものが存在することを示せ．
  \item 整数 $k$ で，$f(k)\neq0$ であり，かつ $f(k)$ が $p_1,\dots,p_n$ のいずれとも異なる相異なる2つの素数でともに割り切れるものが存在することを示せ．
\end{enumerate}

$n$ を2以上の整数とする．次の2つの条件をともにみたす正の整数 $N$ を考える．
\begin{itemize}
  \item[1°] $N$ を $n$ 進法で表すと，$0,1,\dots,n-1$ の数字がそれぞれちょうど $3n^2$ 個ずつ現れる．
  \item[2°] $N$ を $4n$ 進法で表すと，$0,1,\dots,4n-1$ の数字がそれぞれちょうど1個ずつ現れる．
\end{itemize}
\begin{enumerate}
  \item 条件をみたす $N$ が存在するような $n$ をすべて求め，そのときの $N$ の個数を求めよ．
  \item (1) の $N$ のうち，9の倍数であるものの個数を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $n$ を正の整数とし，$a,\ b$ を偶奇の異なる $0$ 以上 $9$ 以下の整数とする．各 $d_i$ が $a$ または $b$ である $2^n$ 個の列 $(d_{n-1},\dots,d_1,d_0)$ のうち，
  $N=\displaystyle\sum_{i=0}^{n-1}d_i\cdot10^i$ が $2^n$ で割り切れるものはちょうど1つであることを示せ．
  \item $n\geqq4$ とする．$n$ 桁の正の整数で，各桁に現れる数字が高々2種類であり，かつ $2^n$ で割り切れるものの個数を求めよ．
\end{enumerate}

$n$ を自然数とする．質量（単位 g）が正の整数である $n$ 個のおもり（同じ質量のものがあってもよい）を用意し，天秤を1回だけ使って物体の質量を量る．物体は一方の皿にのせ，おもりはどちらの皿にのせてもよく，使わないおもりがあってもよい．つり合ったとき，物体の質量がわかるものとする．

いま，$1$ g から $N$ g までのどの整数値の質量の物体も，この方法で量れるとする．
\begin{enumerate}
  \item $N\leqq\dfrac{3^n-1}2$ であることを示せ．
  \item $N=\dfrac{3^n-1}2$ であるならば，おもりの質量は $1,\ 3,\ 3^2,\ \dots,\ 3^{n-1}$ であることを示せ．また，逆にこの $n$ 個のおもりで $1$ g から $\dfrac{3^n-1}2$ g までのどの整数値の質量も量れることを示せ．
\end{enumerate}

自然数 $n$ に対し，$2^k$ が $n$ を割り切るような0以上の整数 $k$ の最大値を $f(n)$ とする．また整数 $p,q$ に対し，$\min\{p,q\}$ は $p,q$ のうち大きくない方を表す．$L$ を自然数とし，$N=2^L$ とする．
\begin{enumerate}
  \item 自然数 $m,n$ について，$f(m)\neq f(n)$ ならば $f(m+n)=\min\{f(m),f(n)\}$，$f(m)=f(n)$ ならば $f(m+n)>f(m)$ であることを示せ．
  \item $1\leqq m\leqq N$，$1\leqq n\leqq N$ をみたす整数の組 $(m,n)$ のうち，$f(m+n)=\min\{f(m),f(n)\}$ をみたすものの個数を $L$ で表せ．
  \item $1\leqq m\leqq N$，$1\leqq n\leqq N$ をみたす整数の組 $(m,n)$ のうち，$f(m+n)\geqq\min\{f(m),f(n)\}+2$ をみたすものの個数を $L$ で表せ．
\end{enumerate}

正の整数の組 $(a,b,c)$ について，次の個数を求めよ．
\begin{enumerate}
  \item $abc=2016$ であり，$a,b,c$ の最大公約数が1であるもの．
  \item $a,b,c$ の最小公倍数が $2016$ であり，$a,b,c$ の最大公約数が1であるもの．
  \item $abc=2016$ かつ $1<a<b<c$ であるもの．
\end{enumerate}
